<div class="proma-accounting proma-accounting-accounts">
  <header class="proma-accounting-page-header"><div><span class="proma-accounting-eyebrow">گردش حساب</span><h2>حساب کاربران</h2><p>مانده و دفترکل مدیران، اپراتورها و وکلا را بررسی کنید.</p></div></header>
  <section class="proma-accounting-balance-guide"><h3>اثر عملیات روی مانده</h3><div><strong>پرداخت به کاربر</strong><span>کاهش مانده</span></div><div><strong>دریافت از کاربر</strong><span>افزایش مانده</span></div></section>
  <section class="proma-accounting-panel">
    <form method="get" class="proma-accounting-filter-bar"><input type="hidden" name="route" value="plugin/accounting/accounts"><div class="proma-accounting-control"><input name="q" value="<?= e($_GET['q'] ?? '') ?>" placeholder="نام، موبایل یا نام کاربری"></div><div class="proma-accounting-control"><select name="balance"><option value="">همه مانده‌ها</option><option value="positive"<?= ($_GET['balance'] ?? '') === 'positive' ? ' selected' : '' ?>>مانده مثبت</option><option value="negative"<?= ($_GET['balance'] ?? '') === 'negative' ? ' selected' : '' ?>>مانده منفی</option><option value="zero"<?= ($_GET['balance'] ?? '') === 'zero' ? ' selected' : '' ?>>مانده صفر</option></select></div><button class="btn btn-primary" type="submit"><i data-feather="search"></i><span>جستجو</span></button></form>
    <div class="table-responsive"><table class="table proma-accounting-table"><thead><tr><th>کاربر</th><th>نقش</th><th>موبایل</th><th>شماره حساب</th><th>مانده</th><th>عملیات</th></tr></thead><tbody><?php foreach (($accounts ?? []) as $account): ?><tr><td><strong><?= e($account['full_name']) ?></strong></td><td><?= e(role_label($account['role'])) ?></td><td dir="ltr"><?= e($account['mobile'] ?: '-') ?></td><td dir="ltr"><?= e($account['account_number'] ?: '-') ?></td><td class="<?= (float) ($account['balance'] ?? 0) >= 0 ? 'proma-accounting-positive' : 'proma-accounting-negative' ?>"><?= money_toman($account['balance']) ?></td><td><a class="btn btn-sm btn-light" href="<?= e(url('plugin/accounting/ledger/' . (int) $account['id'])) ?>"><i data-feather="book-open"></i><span>مشاهده دفترکل</span></a></td></tr><?php endforeach; ?><?php if (empty($accounts)): ?><tr><td colspan="6" class="empty">نتیجه‌ای پیدا نشد.</td></tr><?php endif; ?></tbody></table></div><?= render_pagination($pagination ?? [], static function ($page) { return url('plugin/accounting/accounts', ['q' => $_GET['q'] ?? '', 'balance' => $_GET['balance'] ?? '', 'page' => $page]); }) ?>
  </section>
